import{z as n,x as A,o as s,c as p,q as B,j as o,D as r,d as e,s as i,S as l,b as E}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"铜缆、光纤与衰减","description":"","frontmatter":{"title":"铜缆、光纤与衰减","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/copper-fiber-media.md","filePath":"cs/copper-fiber-media.md","lastUpdated":1791063341000}'),d={name:"cs/copper-fiber-media.md"};function m(C,a,c,h,f,S){const t=A("Mermaid");return s(),p("div",null,[a[2]||(a[2]=B('<h1 id="铜缆、光纤与衰减" tabindex="-1">铜缆、光纤与衰减 <a class="header-anchor" href="#铜缆、光纤与衰减" aria-label="Permalink to &quot;铜缆、光纤与衰减&quot;">​</a></h1><div class="epigraph"><p>电缆的插入损耗随频率上升，光纤的损耗按波长窗口计价；同一 $C=B\\log(1+\\mathrm{SNR})$ 里，$B$ 和 SNR 都是介质给的。</p><footer>—— 据 TIA/EIA 568 类缆规范；ITU-T G.652 / G.655；Kurose and Ross 物理介质节整理</footer></div><p><a href="/cs/clock-recovery-scrambling">上一课</a>假定符号已经过介质到达 CDR。缺口是<strong>介质本身</strong>：双绞线衰减、串扰、长度；光纤的窗口、色散、弯曲。本课不把可插拔光模块的电气约定写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>香农公式里的 \\(B\\) 不是「我想要的带宽」，而是电缆在可接受损耗下还能用的频段。Cat5e/Cat6A 用类别钉串扰与回波；长度 100 m 是信道模型，不是欧姆定律的推论。光纤：1310/1550 nm 窗口损耗低，多模有模态色散限制距离，单模被色散与非线性限制。铜缆上 PAM-4 对回波敏感，所以要回波抵消——这是 SNR 工程，不是新的 MAC。</p><p>无线后课的路径损耗换介质，公式同类：距离吃 SNR。</p><p><span class="marginnote">「光纤无限带宽」是口号。窗口有限，放大器有噪声系数，相干光还有相位噪声。本课只钉衰减与带宽谁在约束 \\(C\\)。</span></p><p><span class="marginnote">dBm 是以 1 mW 为基准的对数功率单位：0 dBm 就是 1 mW，−20 dBm 是它的百分之一。链路预算全程用对数加减，是因为功率从发射到接收动辄差几个数量级，线性数字写不动也算不便。</span></p><p><span class="marginnote">初学者容易以为 Cat6A「支持 10G」是线芯更粗、能扛更大电流；实际类别钉的是高频段的串扰与回波指标——10G 靠的是在同一根线里挤进更宽的可用频段 \\(B\\)，再靠 DSP 把损伤压回去。</span></p><h3 id="介质给-与-snr" tabindex="-1">介质给 \\(B\\) 与 SNR <a class="header-anchor" href="#介质给-与-snr" aria-label="Permalink to &quot;介质给 $B$ 与 SNR&quot;">​</a></h3><p>类别与窗口不是营销标签，而是容量公式的输入。换介质不换 MAC 地址；PCS 把损伤挡在 PHY。延迟主要是距离，不是「光比电快」。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对照三栏：介质、主导损伤、典型距离。双绞：衰减 + NEXT/FEXT。多模：模态色散。单模：损耗、色度色散、PMD。画：发射功率 − 损耗 − 余量 ≥ 接收灵敏度，剩余即 SNR 预算。</p>',13)),(s(),o(l,null,{default:r(()=>[i(t,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20TX%5B%22%E5%8F%91%E5%B0%84%E5%8A%9F%E7%8E%87%22%5D%20--%3E%20LOSS%5B%22%E8%A1%B0%E5%87%8F%E4%B8%8E%E4%B8%B2%E6%89%B0%22%5D%0A%20%20LOSS%20--%3E%20RX%5B%22%E5%88%B0%E8%BE%BE%E5%8A%9F%E7%8E%87%22%5D%0A%20%20RX%20--%3E%20SNR%5B%22SNR%20%E8%BF%9B%E5%AE%B9%E9%87%8F%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"机制",tabindex:"-1"},[e("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=E("p",null,[e("主干"),E("a",{href:"/cs/frame-mac"},"帧"),e("不关心是铜还是光：PCS 把介质差异挡在 PHY。换介质会换调制与 FEC，MAC 帧格式可保持。这是分层：物理损伤不上浮成 IP 选项。")],-1)),a[5]||(a[5]=E("p",null,"选择：机房内短距用铜便宜；跨楼用多模；跨城用单模。类别升级是为了给更高 \\(R_s\\) 留 \\(B\\)，否则只能降阶或缩短。",-1)),(s(),o(l,null,{default:r(()=>[i(t,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E8%A6%81%E9%80%89%E4%BB%8B%E8%B4%A8%22%5D%20--%3E%20CU%5B%22%E9%93%9C%E7%BC%86%E5%8F%8C%E7%BB%9E%22%5D%0A%20%20Q%20--%3E%20MM%5B%22%E5%A4%9A%E6%A8%A1%E5%85%89%E7%BA%A4%22%5D%0A%20%20Q%20--%3E%20SM%5B%22%E5%8D%95%E6%A8%A1%E5%85%89%E7%BA%A4%22%5D%0A%20%20CU%20--%3E%20CUI%5B%22%E4%B8%BB%E5%AF%BC%E6%8D%9F%E4%BC%A4%EF%BC%9A%E8%A1%B0%E5%87%8F%E4%B8%8E%E4%B8%B2%E6%89%B0%20%C2%B7%20%E7%BA%A6%20100%20m%22%5D%0A%20%20MM%20--%3E%20MMI%5B%22%E4%B8%BB%E5%AF%BC%E6%8D%9F%E4%BC%A4%EF%BC%9A%E6%A8%A1%E6%80%81%E8%89%B2%E6%95%A3%20%C2%B7%20%E8%B7%A8%E6%A5%BC%E6%95%B0%E7%99%BE%E7%B1%B3%22%5D%0A%20%20SM%20--%3E%20SMI%5B%22%E4%B8%BB%E5%AF%BC%E6%8D%9F%E4%BC%A4%EF%BC%9A%E8%89%B2%E6%95%A3%E4%B8%8E%E9%9D%9E%E7%BA%BF%E6%80%A7%20%C2%B7%20%E8%B7%A8%E5%9F%8E%E5%85%AC%E9%87%8C%E7%BA%A7%22%5D%0A"})]),fallback:r(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=B('<p><span class="marginnote">模态色散可以想象成宽走廊里的人群斜穿：沿中线走的先到，斜着折返的后到，光脉冲被自己「拉宽」，前一个码元就糊进后一个。单模纤芯细到只留一条路径，脉冲形状保得住，距离因此能拉到公里级。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入非线性薛定谔方程，不把 DWDM 信道间隔写完——下一课光模块与 WDM。后课默认：链路预算 = 功率与损伤；类别与光纤类型是 \\(B\\)、SNR 的来源。</p><p>不要用「光比电快」当定理：延迟主要是距离与转发，不是电子质量。</p><p>下一课<a href="/cs/optical-transceivers-wdm">光模块与 WDM</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>铜缆：长度、类别约束衰减与串扰。</li><li>光纤：窗口、色散、模态限制距离与 \\(B\\)。</li><li>预算进入上一课的 \\(C\\)，不改 MAC。</li><li>后课只引用本课钉死的对象，不从该领域总问题重开。</li><li>出处：TIA-568；ITU-T G.65x；Kurose and Ross。</li></ul>',7))])}const T=n(d,[["render",m]]);export{u as __pageData,T as default};
